<?php
function adminEscape($v): string { return htmlspecialchars((string)$v, ENT_QUOTES, 'UTF-8'); }
function adminPages(): array { return ['dashboard'=>'Overview','homepage'=>'Homepage','copy'=>'Website text','offerings'=>'Spaces & experiences','bookings'=>'Booking details','gallery'=>'Media library','about'=>'About the venue','contact'=>'Contact & location','seo'=>'SEO & discovery','account'=>'Account']; }
function adminStart(string $active, string $title, array $settings): void { ?>
<!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><meta name="robots" content="noindex,nofollow"><title><?= adminEscape($title) ?> | Venue administration</title><link rel="stylesheet" href="../assets/css/admin.css?v=4"><script src="../assets/js/admin.js?v=4" defer></script></head><body class="admin-app">
<a class="admin-skip" href="#workspace">Skip to workspace</a>
<aside class="sidebar" id="admin-navigation"><a class="admin-brand" href="index.php"><span class="brand-mark">CG</span><span>Charles Gala<small>VENUE MANAGEMENT</small></span></a><div class="workspace-label">WORKSPACE</div><nav aria-label="Administration"><?php $icons=['◫','⌂','Aa','▦','₹','▧','◉','⌖','↗','◎']; $i=0; foreach(adminPages() as $key=>$label): ?><a href="<?= $key==='seo'?'seo.php':'index.php?page='.$key ?>" <?= $active===$key?'aria-current="page"':'' ?>><span aria-hidden="true"><?= $icons[$i++] ?></span><?= adminEscape($label) ?></a><?php endforeach; ?></nav><div class="sidebar-bottom"><span class="status-dot"></span> Website content manager<p>Make every first impression count.</p><a href="../" target="_blank" rel="noopener">Open website ↗</a></div></aside>
<div class="admin-shell"><header class="topbar"><button class="sidebar-toggle secondary" type="button" aria-controls="admin-navigation" aria-expanded="false">☰ <span>Menu</span></button><div class="breadcrumb">Workspace <span>/</span> <strong><?= adminEscape($title) ?></strong></div><div class="top-actions"><a class="preview-link" href="../" target="_blank" rel="noopener">View website ↗</a><span class="avatar" aria-hidden="true"><?= adminEscape(strtoupper(substr($_SESSION['cgv_admin_user']??'A',0,1))) ?></span><span class="account-name"><?= adminEscape($_SESSION['cgv_admin_user']??'Administrator') ?></span><a href="logout.php">Sign out</a></div></header><main id="workspace" tabindex="-1"><div class="page-heading"><div><p class="eyebrow">CHARLES GALA VENUE</p><h1><?= adminEscape($title) ?></h1></div><span class="workspace-badge">Administration</span></div>
<?php }
function adminEnd(): void { ?><footer class="admin-footer">Charles Gala Venue <span>Content & website management</span></footer></main></div></body></html><?php }
function adminField(string $name, string $label, $value='', string $type='text', string $hint=''): void { ?><label class="field"><span><?= adminEscape($label) ?></span><?php if($type==='textarea'): ?><textarea name="<?= adminEscape($name) ?>" rows="3"><?= adminEscape($value) ?></textarea><?php else: ?><input name="<?= adminEscape($name) ?>" type="<?= adminEscape($type) ?>" value="<?= adminEscape($value) ?>"><?php endif; ?><?php if($hint): ?><small><?= adminEscape($hint) ?></small><?php endif; ?></label><?php }
function adminFormStart(string $action, string $csrf): void { ?><form method="post" enctype="multipart/form-data"><input type="hidden" name="csrf_token" value="<?= adminEscape($csrf) ?>"><input type="hidden" name="action" value="<?= adminEscape($action) ?>"><?php }
function adminSave(string $label='Save changes'): void { ?><div class="form-actions"><span data-save-state>Changes are published when saved.</span><button type="submit"><?= adminEscape($label) ?></button></div></form><?php }
